import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.BAQ5ZYJQ.js";const k=JSON.parse('{"title":"Where errand writes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/storage.md","filePath":"guide/storage.md","lastUpdated":1794577911000}'),o={name:"guide/storage.md"};function r(h,e,n,d,p,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="where-errand-writes" tabindex="-1">Where errand writes <a class="header-anchor" href="#where-errand-writes" aria-label="Permalink to &quot;Where errand writes&quot;">​</a></h1><p>errand writes in three kinds of places, on every machine it works on:</p><table tabindex="0"><thead><tr><th>place</th><th>what</th><th>size</th></tr></thead><tbody><tr><td><strong>the project</strong>: <code>errand-outputs/</code> at its root ( over there, in the project&#39;s copy )</td><td>every run&#39;s record, what was built, errand&#39;s bookkeeping</td><td>grows with use</td></tr><tr><td><strong>per user</strong>: <code>~/.cache/errand/</code></td><td>errand&#39;s own sources and, if needed, a Python for itself; sockets, locks and pids of what is running</td><td>a few MB, plus a Python if errand made one</td></tr><tr><td><strong>per machine</strong>: a directory in <code>$XDG_RUNTIME_DIR</code>, else the temporary directory</td><td>the claims of <a href="./machine">machine sharing</a></td><td>a few files</td></tr></tbody></table><p>Then come the environments your layers build: a micromamba environment, a venv, a container image. They go where the declaration says, and each layer has a parameter to choose that.</p><p>Everything that grows belongs to a project, so you choose where it goes. The per-user directory holds only what is live, and cleans itself up ( see <a href="./agents#leaving-nothing-behind">leaving nothing behind</a> ).</p><h2 id="the-project-errand-outputs" tabindex="-1">The project: <code>errand-outputs/</code> <a class="header-anchor" href="#the-project-errand-outputs" aria-label="Permalink to &quot;The project: \`errand-outputs/\`&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>errand-outputs/</span></span>
<span class="line"><span>  runs/       the record of every run</span></span>
<span class="line"><span>  builds/     what errand built: the Windows images, the records of what was set up</span></span>
<span class="line"><span>  state/      errand&#39;s bookkeeping: plans, history, the output kept for \`errand attach\`</span></span></code></pre></div><p>What each holds is in <a href="./output#what-else-is-on-disk">Where the output goes</a>.</p><p>Three settings move it, from the broadest to the most specific:</p><table tabindex="0"><thead><tr><th>setting</th><th>scope</th><th>example</th></tr></thead><tbody><tr><td><code>errand.configure( outputs_directory = … )</code></td><td>the project, on every machine</td><td><code>&quot;errand-outputs&quot;</code> ( the default ), or <code>&quot;/data/me/proj-out&quot;</code></td></tr><tr><td><code>ERRAND_OUTPUTS_DIR</code></td><td>one machine: an environment variable</td><td><code>export ERRAND_OUTPUTS_DIR=/scratch/me/proj-out</code></td></tr><tr><td><code>Ssh( errand_outputs_directory = … )</code></td><td>the project&#39;s copy on that host</td><td><code>&quot;/scratch/me/proj-out&quot;</code></td></tr></tbody></table><p>A relative path is from the project root. With <code>errand_outputs_directory</code>, the project&#39;s copy over there holds a symlink <code>errand-outputs</code> to the directory, so nothing else changes. What the copy&#39;s own <code>errand-outputs/</code> already held is moved there at the next push. The two other settings move nothing: a run writes to the new place, and the old one stays as it was.</p><p><code>builds/</code> can go somewhere else on its own, with <code>errand.configure( builds_directory = … )</code>: another disk, or a directory several projects share, so that they share one Windows image. It is the same path on every machine, so an absolute path must exist on each of them.</p><h2 id="over-ssh-the-project-s-copy" tabindex="-1">Over Ssh: the project&#39;s copy <a class="header-anchor" href="#over-ssh-the-project-s-copy" aria-label="Permalink to &quot;Over Ssh: the project&#39;s copy&quot;">​</a></h2><p><code>Ssh( root = … )</code> is where the project is copied over there. <strong>Without it, the copy goes to the same path as here</strong>: <code>/home/me/proj</code> here means <code>/home/me/proj</code> over there. On a cluster, that is usually the home directory, so you will want <code>root</code> to point at a work or scratch disk:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">errand.Ssh( </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;cluster&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">root</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/scratch/me/proj&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span></code></pre></div><p>The copy holds everything that follows from it: <code>errand-outputs/</code> ( unless <code>errand_outputs_directory</code> says otherwise ), a <a href="./layers/venv"><code>Uv</code></a> venv, and a container image declared with a relative path.</p><h2 id="environments" tabindex="-1">Environments <a class="header-anchor" href="#environments" aria-label="Permalink to &quot;Environments&quot;">​</a></h2><p>Each layer that builds something says where it goes:</p><table tabindex="0"><thead><tr><th>layer</th><th>parameter</th><th>default</th></tr></thead><tbody><tr><td><a href="./layers/micromamba"><code>Micromamba</code></a></td><td><code>root_prefix</code>: environments and package cache</td><td><code>$MAMBA_ROOT_PREFIX</code>, else <code>~/.mamba</code> or <code>~/micromamba</code></td></tr><tr><td><a href="./layers/venv"><code>Uv</code></a></td><td><code>path</code></td><td><code>.venv</code>, in the project</td></tr><tr><td><a href="./layers/venv"><code>Venv</code></a></td><td><code>python</code>: the venv is the directory above its <code>bin/</code></td><td>—</td></tr><tr><td><a href="./layers/containers"><code>Apptainer</code></a></td><td><code>image</code>: relative to the project, or absolute</td><td>—</td></tr><tr><td><a href="./layers/containers"><code>Apptainer</code></a></td><td><code>scratch</code>: where the build unpacks and downloads</td><td>apptainer&#39;s own: <code>/tmp</code> and <code>~/.apptainer/cache</code></td></tr><tr><td><a href="./layers/windows"><code>Windows</code></a></td><td><code>builds_directory</code>, see above</td><td><code>errand-outputs/builds/windows/</code></td></tr></tbody></table><h2 id="the-per-user-directory-cache-errand" tabindex="-1">The per-user directory: <code>~/.cache/errand/</code> <a class="header-anchor" href="#the-per-user-directory-cache-errand" aria-label="Permalink to &quot;The per-user directory: \`~/.cache/errand/\`&quot;">​</a></h2><p>On a machine reached by <code>Ssh</code>, errand puts its sources here ( about 1 MB per checkout that asked ). If the machine has no usable Python, it also makes one here for itself, with <code>uv</code> and maybe the uv it fetched first. That is tens of MB, once. The rest is live: the directories of the agents and of the hub, a warm Slurm allocation, the virtual machines that are booted. These go away by themselves.</p><p>It is in the home directory on purpose: on a cluster, the home is what the login node and the compute nodes share, so what errand finds or makes on the login node is what a job uses on a node. There is no setting to move it. If your home really has no room, replace it by a symlink to a disk that the nodes also see:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.cache/errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /work/me/errand-cache</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # or rm -rf it: errand remakes what it needs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /work/me/errand-cache</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.cache/errand</span></span></code></pre></div><p>Removing <code>~/.cache/errand</code> is always safe when nothing is running: it undoes everything errand made for itself.</p><h2 id="the-tools-own-caches" tabindex="-1">The tools&#39; own caches <a class="header-anchor" href="#the-tools-own-caches" aria-label="Permalink to &quot;The tools&#39; own caches&quot;">​</a></h2><p>Some tools that errand runs keep caches of their own in the home directory: <code>pip</code> in <code>~/.cache/pip</code>, <code>uv</code> in <code>~/.cache/uv</code>, apptainer in <code>~/.apptainer/cache</code>. errand leaves them alone. To move them, set their variables in your account&#39;s environment over there ( <code>~/.bashrc</code>, say ):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PIP_CACHE_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/scratch/me/cache/pip</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> UV_CACHE_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/scratch/me/cache/uv</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> APPTAINER_CACHEDIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/scratch/me/cache/apptainer</span></span></code></pre></div><p>For apptainer builds, <a href="./layers/containers"><code>Apptainer( scratch = … )</code></a> does that for you.</p><h2 id="a-small-home-in-short" tabindex="-1">A small home, in short <a class="header-anchor" href="#a-small-home-in-short" aria-label="Permalink to &quot;A small home, in short&quot;">​</a></h2><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">errand.Ssh( </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;cluster&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">            root</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/scratch/me/proj&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,                         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the project&#39;s copy</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">            errand_outputs_directory</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/scratch/me/proj-out&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># runs, builds, state</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">errand.Micromamba( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;proj&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">root_prefix</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/scratch/me/mamba&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># environments</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">errand.Apptainer( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;proj.sif&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">recipe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;proj.def&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">scratch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/scratch/me/tmp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span></code></pre></div><p>Plus, if even a few MB are too many, the symlink for <code>~/.cache/errand</code>, and the tools&#39; cache variables.</p>`,31)])])}const u=t(o,[["render",r]]);export{k as __pageData,u as default};
